class RetryManager:
    """Advanced retry manager with exponential backoff."""

    def __init__(self, max_retries: int = 3, base_delay: float = 1.0,
                 max_delay: float = 60.0, exponential_base: float = 2.0):
        """Initialize retry manager.

        Args:
            max_retries: Maximum number of retry attempts
            base_delay: Base delay between retries (seconds)
            max_delay: Maximum delay between retries (seconds)
            exponential_base: Base for exponential backoff
        """
        self.max_retries = max_retries
        self.base_delay = base_delay
        self.max_delay = max_delay
        self.exponential_base = exponential_base

    def retry_with_backoff(self, func: Callable, *args, 
                          retryable_exceptions: tuple = (Exception,),
                          **kwargs) -> Any:
        """Execute function with exponential backoff retry."""
        last_exception = None

        for attempt in range(self.max_retries + 1):
            try:
                return func(*args, **kwargs)
            except retryable_exceptions as e:
                last_exception = e

                if attempt == self.max_retries:
                    logger.error("All retry attempts exhausted for %s", func.__name__)
                    raise

                # Calculate delay with exponential backoff
                delay = min(
                    self.base_delay * (self.exponential_base ** attempt),
                    self.max_delay
                )

                logger.warning(
                    "Attempt %d failed for %s, retrying in %.2fs: %s",
                    attempt + 1, func.__name__, delay, str(e)
                )

                time.sleep(delay)

        raise last_exception


class FailoverManager:
    """Manages failover between primary and backup systems."""

    def __init__(self):
        """Initialize failover manager."""
        self.primary_services = {}
        self.backup_services = {}
        self.current_services = {}
        self.health_checks = {}

    def register_service(self, service_name: str, primary_service: Any,
                        backup_service: Any, health_check: Callable):
        """Register a service with primary and backup instances."""
        self.primary_services[service_name] = primary_service
        self.backup_services[service_name] = backup_service
        self.current_services[service_name] = primary_service
        self.health_checks[service_name] = health_check

        logger.info("Registered service %s with failover capability", service_name)

    def execute_with_failover(self, service_name: str, operation: str,
                             *args, **kwargs) -> Any:
        """Execute operation with automatic failover."""
        if service_name not in self.current_services:
            raise ValueError(f"Service {service_name} not registered")

        current_service = self.current_services[service_name]

        try:
            # Try primary service
            if hasattr(current_service, operation):
                return getattr(current_service, operation)(*args, **kwargs)
            else:
                raise AttributeError(f"Operation {operation} not found on service")

        except Exception as e:
            logger.warning("Primary service %s failed: %s", service_name, str(e))

            # Attempt failover to backup
            if self._failover_to_backup(service_name):
                backup_service = self.current_services[service_name]
                try:
                    return getattr(backup_service, operation)(*args, **kwargs)
                except Exception as backup_error:
                    logger.error("Backup service %s also failed: %s", 
                               service_name, str(backup_error))
                    raise
            else:
                raise

    def _failover_to_backup(self, service_name: str) -> bool:
        """Failover to backup service if available."""
        if service_name not in self.backup_services:
            return False

        # Check if backup service is healthy
        health_check = self.health_checks.get(service_name)
        if health_check:
            try:
                backup_service = self.backup_services[service_name]
                if not health_check(backup_service):
                    logger.error("Backup service %s failed health check", service_name)
                    return False
            except Exception as e:
                logger.error("Health check failed for backup service %s: %s", 
                           service_name, str(e))
                return False

        # Switch to backup
        self.current_services[service_name] = self.backup_services[service_name]
        logger.info("Failed over to backup service for %s", service_name)
        return True

    def check_service_health(self, service_name: str) -> bool:
        """Check health of current service."""
        if service_name not in self.current_services:
            return False

        health_check = self.health_checks.get(service_name)
        if not health_check:
            return True  # No health check defined, assume healthy

        try:
            return health_check(self.current_services[service_name])
        except Exception as e:
            logger.error("Health check failed for %s: %s", service_name, str(e))
            return False

    def restore_primary(self, service_name: str) -> bool:
        """Attempt to restore primary service."""
        if service_name not in self.primary_services:
            return False

        # Check if primary is healthy again
        health_check = self.health_checks.get(service_name)
        if health_check:
            try:
                primary_service = self.primary_services[service_name]
                if health_check(primary_service):
                    self.current_services[service_name] = primary_service
                    logger.info("Restored primary service for %s", service_name)
                    return True
            except Exception as e:
                logger.warning("Primary service %s still unhealthy: %s", 
                             service_name, str(e))

        return False


class ErrorRecoveryOrchestrator:
    """Main orchestrator for enterprise error recovery."""

    def __init__(self):
        """Initialize error recovery orchestrator."""
        self.circuit_breakers = {}
        self.retry_manager = RetryManager()
        self.failover_manager = FailoverManager()
        self.error_history = []
        self.recovery_statistics = {
            'total_errors': 0,
            'recovered_errors': 0,
            'unrecovered_errors': 0,
            'recovery_strategies_used': {}
        }

    def handle_error(self, error: Exception, context: ErrorContext) -> RecoveryResult:
        """Handle error with appropriate recovery strategy."""
        start_time = time.perf_counter()

        # Record error
        self.error_history.append(context)
        self.recovery_statistics['total_errors'] += 1

        # Determine recovery strategy
        strategy = self._determine_recovery_strategy(error, context)

        # Execute recovery
        try:
            result = self._execute_recovery(error, context, strategy)
            if result.success:
                self.recovery_statistics['recovered_errors'] += 1
            else:
                self.recovery_statistics['unrecovered_errors'] += 1

            # Update strategy statistics
            strategy_name = strategy.value
            if strategy_name not in self.recovery_statistics['recovery_strategies_used']:
                self.recovery_statistics['recovery_strategies_used'][strategy_name] = 0
            self.recovery_statistics['recovery_strategies_used'][strategy_name] += 1

            result.recovery_time = time.perf_counter() - start_time
            return result

        except Exception as recovery_error:
            logger.error("Recovery failed: %s", str(recovery_error))
            self.recovery_statistics['unrecovered_errors'] += 1

            return RecoveryResult(
                success=False,
                strategy_used=strategy,
                attempts_made=1,
                recovery_time=time.perf_counter() - start_time,
                final_error=recovery_error
            )

    def _determine_recovery_strategy(self, error: Exception, 
                                   context: ErrorContext) -> RecoveryStrategy:
        """Determine appropriate recovery strategy based on error and context."""

        # Critical errors require manual intervention
        if context.severity == ErrorSeverity.CRITICAL:
            return RecoveryStrategy.MANUAL_INTERVENTION

        # Network/timeout errors - use retry with circuit breaker
        if any(keyword in str(error).lower() for keyword in 
               ['timeout', 'connection', 'network', 'unreachable']):
            return RecoveryStrategy.CIRCUIT_BREAKER

        # Service availability errors - use failover
        if any(keyword in str(error).lower() for keyword in 
               ['service unavailable', 'service down', '503', '502']):
            return RecoveryStrategy.FAILOVER

        # Transient errors - simple retry
        if any(keyword in str(error).lower() for keyword in 
               ['temporary', 'transient', 'rate limit']):
            return RecoveryStrategy.RETRY

        # For high severity errors, use graceful degradation
        if context.severity == ErrorSeverity.HIGH:
            return RecoveryStrategy.GRACEFUL_DEGRADATION

        # Default to retry for other errors
        return RecoveryStrategy.RETRY

    def _execute_recovery(self, error: Exception, context: ErrorContext,
                         strategy: RecoveryStrategy) -> RecoveryResult:
        """Execute the determined recovery strategy."""

        if strategy == RecoveryStrategy.RETRY:
            return self._execute_retry_recovery(error, context)
        elif strategy == RecoveryStrategy.CIRCUIT_BREAKER:
            return self._execute_circuit_breaker_recovery(error, context)
        elif strategy == RecoveryStrategy.FAILOVER:
            return self._execute_failover_recovery(error, context)
        elif strategy == RecoveryStrategy.GRACEFUL_DEGRADATION:
            return self._execute_graceful_degradation(error, context)
        else:
            return RecoveryResult(
                success=False,
                strategy_used=strategy,
                attempts_made=0,
                recovery_time=0.0,
                final_error=Exception("Manual intervention required")
            )

    def _execute_retry_recovery(self, error: Exception, 
                               context: ErrorContext) -> RecoveryResult:
        """Execute retry-based recovery."""
        attempts = 0

        def retry_operation():
            nonlocal attempts
            attempts += 1
            # This would normally re-execute the failed operation
            # For demonstration, we'll simulate success after a few attempts
            if attempts >= 2:
                return True
            raise error

        try:
            self.retry_manager.retry_with_backoff(retry_operation)
            return RecoveryResult(
                success=True,
                strategy_used=RecoveryStrategy.RETRY,
                attempts_made=attempts,
                recovery_time=0.0  # Will be set by caller
            )
        except Exception as e:
            return RecoveryResult(
                success=False,
                strategy_used=RecoveryStrategy.RETRY,
                attempts_made=attempts,
                recovery_time=0.0,
                final_error=e
            )

    def _execute_circuit_breaker_recovery(self, error: Exception,
                                         context: ErrorContext) -> RecoveryResult:
        """Execute circuit breaker recovery."""
        component = context.component

        if component not in self.circuit_breakers:
            self.circuit_breakers[component] = CircuitBreaker()

        circuit_breaker = self.circuit_breakers[component]

        try:
            # Record failure in circuit breaker
            circuit_breaker._record_failure()

            # If circuit is open, don't attempt recovery
            if circuit_breaker.get_state() == CircuitBreakerState.OPEN:
                return RecoveryResult(
                    success=False,
                    strategy_used=RecoveryStrategy.CIRCUIT_BREAKER,
                    attempts_made=0,
                    recovery_time=0.0,
                    final_error=Exception("Circuit breaker is OPEN")
                )

            # Attempt recovery with circuit breaker protection
            @circuit_breaker
            def protected_operation():
                # Simulate recovery operation
                return True

            protected_operation()

            return RecoveryResult(
                success=True,
                strategy_used=RecoveryStrategy.CIRCUIT_BREAKER,
                attempts_made=1,
                recovery_time=0.0
            )

        except Exception as e:
            return RecoveryResult(
                success=False,
                strategy_used=RecoveryStrategy.CIRCUIT_BREAKER,
                attempts_made=1,
                recovery_time=0.0,
                final_error=e
            )

    def _execute_failover_recovery(self, error: Exception,
                                  context: ErrorContext) -> RecoveryResult:
        """Execute failover recovery."""
        component = context.component
        operation = context.operation

        try:
            # Attempt failover (this would normally call the actual operation)
            # For demonstration, we'll simulate successful failover
