    def get_circuit_breaker(self, component: str) -> CircuitBreaker:
        """Get or create circuit breaker for component."""
        if component not in self.circuit_breakers:
            self.circuit_breakers[component] = CircuitBreaker()
        return self.circuit_breakers[component]

    def get_recovery_statistics(self) -> Dict[str, Any]:
        """Get comprehensive recovery statistics."""
        total_errors = self.recovery_statistics['total_errors']

        stats = dict(self.recovery_statistics)

        # Calculate success rate
        if total_errors > 0:
            stats['recovery_success_rate'] = (
                self.recovery_statistics['recovered_errors'] / total_errors
            )
        else:
            stats['recovery_success_rate'] = 0.0

        # Add circuit breaker states
        stats['circuit_breaker_states'] = {
            component: breaker.get_state().value
            for component, breaker in self.circuit_breakers.items()
        }

        # Recent error summary
        recent_errors = self.error_history[-10:]  # Last 10 errors
        stats['recent_error_summary'] = {
            'total': len(recent_errors),
            'by_severity': {},
            'by_component': {}
        }

        for error in recent_errors:
            # Count by severity
            severity = error.severity.value
            if severity not in stats['recent_error_summary']['by_severity']:
                stats['recent_error_summary']['by_severity'][severity] = 0
            stats['recent_error_summary']['by_severity'][severity] += 1

            # Count by component
            component = error.component
            if component not in stats['recent_error_summary']['by_component']:
                stats['recent_error_summary']['by_component'][component] = 0
            stats['recent_error_summary']['by_component'][component] += 1

        return stats

    def reset_statistics(self):
        """Reset recovery statistics."""
        self.recovery_statistics = {
            'total_errors': 0,
            'recovered_errors': 0,
            'unrecovered_errors': 0,
            'recovery_strategies_used': {}
        }
        self.error_history.clear()
        logger.info("Recovery statistics reset")


